def find_median(a, b):
    # Binary search the cut position in the shorter array, so the loop runs
    # log(min(n, m)) times regardless of how long the other array is.
    if len(a) > len(b):
        a, b = b, a

    n, m = len(a), len(b)
    half = (n + m + 1) // 2
    low, high = 0, n

    while low <= high:
        i = (low + high) // 2      # values a[:i] go left
        j = half - i               # forced: the two left parts must total `half`

        # Missing neighbours become infinities, which removes every
        # empty-array and one-sided-cut special case.
        a_left = a[i - 1] if i > 0 else float('-inf')
        a_right = a[i] if i < n else float('inf')
        b_left = b[j - 1] if j > 0 else float('-inf')
        b_right = b[j] if j < m else float('inf')

        if a_left <= b_right and b_left <= a_right:
            if (n + m) % 2 == 1:
                return float(max(a_left, b_left))
            return (max(a_left, b_left) + min(a_right, b_right)) / 2.0

        if a_left > b_right:
            high = i - 1           # cut in `a` is too far right
        else:
            low = i + 1

    return 0.0

