    const i = Math.floor((low + high) / 2); // values a[:i] go left
    const j = half - i;                     // forced by the half-size rule

    // Missing neighbours become infinities, which removes every
    // empty-array and one-sided-cut special case.
    const aLeft = i > 0 ? a[i - 1] : -Infinity;
    const aRight = i < n ? a[i] : Infinity;
    const bLeft = j > 0 ? b[j - 1] : -Infinity;
    const bRight = j < m ? b[j] : Infinity;

    if (aLeft <= bRight && bLeft <= aRight) {
      if ((n + m) % 2 === 1) return Math.max(aLeft, bLeft);
      return (Math.max(aLeft, bLeft) + Math.min(aRight, bRight)) / 2;
    }

    if (aLeft > bRight) high = i - 1;       // cut in `a` is too far right
    else low = i + 1;
  }

